@module paramAutomation  src=paramAutomation.lua  loc=447  mode=chunk  self=pa
@deps cm, ds, facade, ccm

# Invariants & contracts
  @invariant  automation bus is 126 — 127 is wiring's parking bus, wiring allocates 0..125  @ 4
  @invariant  a binding is the track's, not the take's: every take on it authors the same lane  @ 5
  @invariant  authored (chan,lane) codes are track-unique; bus codes project-unique  @ 6
  @invariant  one binding per (fx,param): the target's single plink; a rival would win it silently  @ 7

# Shapes
  @shape  paramAutomation (ds track key) = { [chan] = { [lane] = binding } }  @ 8
  @shape  binding = { busCode=int, trackGuid=str, fxGuid=str, param=int, scale=num, offset=num, label=str }  @ 9
  @shape  trackSpec = { filter={ {src=code,dst=code},... }, listen={ {code,fxGuid,param,scale,offset},... }, sends={dstGuid,...} }  @ 10
  @shape  paramFrecency (ds global) = { [fxIdent] = { n=int, params={ [paramIndex]={s=num,n0=int} } } }  @ 11

# Imports
  @require util = 'util'  @ 13
      @contract  apply() is a full-project idempotent reconcile; mirror-matching tracks are untouched  @ 12

# Private state
  @state AUTO_BUS = 126  @ 21
  @state SLOTS = 16  @ 22
  @state META_PEXT = 'P_EXT:ctm_paramAuto'  @ 23
  @state TOP_LANE = 119  @ 24   -- 120..127 are channel-mode messages
  @state P_VALUE, P_SRC, P_DST, P_LISTEN = 0, 16, 32, 48  @ 27
  @state pa = {}  @ 29
  @state DECAY = 0.9  @ 281
  @state paramCache = {}  @ 283   -- [fxGuid] = { count, params, gen, sorted }
  @state frecencyGen = 0  @ 284   -- bumped on every frecency write; stales sorted caches

# Private functions
  @fn arrange()  @ 18
      -- Source-track resolution is logical, not physical: a parked take hosts on the scratch track,
      -- but automates the track owning its slot -- the ds tier names that track, kept current by tp:bind after every bindTake.
  @fn ownerTrack(take)  @ 19
