  @fn trackByGuid(guid)  @ 33-42
  @fn fxIndexByGuid(track, guid)  @ 44-48
  @fn resolveFx(trackGuid, fxGuid)  @ 50-54
  @fn eachTake(visit)  @ 56-64
  @fn eachTrack(visit)  @ 66-68
  @fn boundTrack()  @ 70-72
  -- Gather + desired specs
  @fn gatherBindings()  @ 76-93
  -- Apply
  @fn readMirror(track)  @ 133-138
  @fn writeMirror(track, spec)  @ 140-142
  @fn setPlink(track, fxIdx, param, ccIdx, slot, scale, offset)  @ 144-154
  @fn clearPlink(track, fxIdx, param)  @ 156-160
  @fn writeBanks(track, ccIdx, spec)  @ 162-172
  @fn reconcileAutoSends(track, dstGuids)  @ 176-203
      -- Ours by signature: midi-only send whose src bus is the automation bus.
      -- Encoding mirrors routingManager createSend/readSendChans (bits 14/22, +1-biased).
  @fn applyTrack(track, spec, mirror)  @ 205-237
  -- Allocation
  @fn usedLanes(srcTrack, chan)  @ 243-260
      -- Authored lanes are track-unique (the filter bank is shared per track): used = the
      -- track's bound lanes, plus each of its takes' user cc columns and event-bearing ccs on the channel.
  @fn allocLane(srcTrack, chan)  @ 262-267
  @fn allocBusCode()  @ 269-275
  -- Frecency + param cache
  @fn fxIdentAt(track, fxIdx)  @ 286-289
  @fn bindingFor(cfg, target)  @ 326-333
      -- Where the track already drives this target, if anywhere.

# Public API (pa.*)
  @api pa.computeDesired(bindings)  @ 97-129
      -- Pure: bindings -> { [trackGuid] = trackSpec }. Pooled duplicates collapse
      -- via the seen-keys; slot order is sorted for a stable REAPER image.
  @api pa.frecencyOrder(params, fxScores)  @ 292-305
      @contract  pure, stable: decayed score desc, then param index; fxScores may be nil  @ 291

# Public API (pa:*)
  @api pa:apply()  @ 310-323
      @contract  no-op (and no undo point) when every track's mirror already matches  @ 309
  @api pa:automate(chan, target)  @ 337-357
      @contract  chan is the tracker's 1-based channel; returns the cc lane, or nil + reason  @ 335
      @contract  a target already bound answers on its own channel; asking on another is refused  @ 336
  @api pa:unautomate(chan, lane)  @ 359-366
  @api pa:binding(chan, lane)  @ 368-371
  @api pa:targets()  @ 374-379
      @contract  palette rows from the wiring facade's cone walk; {} without a take or wiring  @ 373
  @api pa:params(trackGuid, fxGuid)  @ 382-403
      @contract  cached per fxGuid (param-count change invalidates); frecency-hot params first  @ 381
  @api pa:bumpFrecency(trackGuid, fxGuid, paramIndex)  @ 406-420
      @contract  advances the ident's use counter; the param's score decays to it, then +1  @ 405
  @api pa:floatFx(trackGuid, fxGuid)  @ 423-428
      @contract  floats the fx ui; true only when pa floated it — caller owns popping it down  @ 422
  @api pa:unfloatFx(trackGuid, fxGuid)  @ 430-433
  @api pa:lastTouched()  @ 436-445
      @contract  last-touched track-fx param as guids + name; nil for take/container/input fx  @ 435

